-- The food library: everyday foods with their nutrients, names and portions, imported from the
-- Bundeslebensmittelschlüssel (BLS) 4.0 of the Max Rubner-Institut (CC BY 4.0). Clients only
-- read it; it changes through migrations generated by scripts/import-foods.ts.

-- Where a food's values come from. Foods BLS lacks can be added later with their own source.
create type public.food_source as enum ('bls');

-- The BLS main groups, from the first letter of a BLS code.
create type public.food_group as enum (
  'bread',
  'cereals',
  'pastries',
  'eggs_and_pasta',
  'fruit',
  'vegetables',
  'legumes_nuts_seeds',
  'potatoes_mushrooms',
  'dairy',
  'drinks',
  'alcoholic_drinks',
  'fats',
  'condiments',
  'sweets',
  'fish',
  'meat',
  'poultry_game_offal',
  'sausages',
  'dishes'
);

-- The units people count portions in. Their names are in the app's translations.
create type public.portion_unit as enum (
  'piece',
  'slice',
  'cup',
  'glass',
  'bowl',
  'plate',
  'tablespoon',
  'teaspoon',
  'handful',
  'serving',
  'can',
  'bottle'
);

create table public.foods (
  -- The source's code, such as the BLS code 'C133000', so that later imports update rows in place.
  id text primary key check (id ~ '^[A-Z0-9]+$'),
  source public.food_source not null,
  food_group public.food_group not null,
  -- Per 100 g. Drinks too, as BLS gives every value per 100 g.
  kcal numeric(6, 1) not null check (kcal >= 0),
  protein_g numeric(5, 2) not null check (protein_g >= 0),
  carbs_g numeric(5, 2) not null check (carbs_g >= 0),
  fat_g numeric(5, 2) not null check (fat_g >= 0),
  fiber_g numeric(5, 2) check (fiber_g >= 0),
  sugar_g numeric(5, 2) check (sugar_g >= 0),
  saturated_fat_g numeric(5, 2) check (saturated_fat_g >= 0),
  salt_g numeric(5, 2) check (salt_g >= 0)
);

create table public.food_names (
  food_id text not null references public.foods (id) on delete cascade,
  -- Any two-letter language code, so that a new language needs rows, not a schema change.
  -- The app falls back to English, which every food has.
  language text not null check (language ~ '^[a-z]{2}$'),
  name text not null check (length(name) between 1 and 120),
  primary key (food_id, language)
);

create table public.food_portions (
  food_id text not null references public.foods (id) on delete cascade,
  unit public.portion_unit not null,
  -- The edible amount of one unit, such as 60 for an egg.
  grams numeric(6, 1) not null check (grams > 0 and grams <= 5000),
  -- The portion the app suggests first. Exactly one per food, checked by the import.
  is_default boolean not null default false,
  primary key (food_id, unit)
);

create unique index food_portions_one_default on public.food_portions (food_id) where is_default;

-- Everyone using the app, including anonymous users, can read the library. There are no
-- insert, update or delete policies, so clients cannot change it, and the privileges are
-- revoked as well so that a policy added by mistake would not be enough.
alter table public.foods enable row level security;
alter table public.food_names enable row level security;
alter table public.food_portions enable row level security;

create policy "Foods are readable by everyone"
  on public.foods for select
  to anon, authenticated
  using (true);

create policy "Food names are readable by everyone"
  on public.food_names for select
  to anon, authenticated
  using (true);

create policy "Food portions are readable by everyone"
  on public.food_portions for select
  to anon, authenticated
  using (true);

revoke insert, update, delete, truncate on public.foods from anon, authenticated;
revoke insert, update, delete, truncate on public.food_names from anon, authenticated;
revoke insert, update, delete, truncate on public.food_portions from anon, authenticated;
